/* ══ REVIEW PAGES ═══════════════════════════════════════════════════════
   The drawing's own pages, outside the product frame: every screen in one
   index, the assessment of today, and the decisions the team is asked for. */
R.review = (args) => {
  const v = args[0] || 'screens';
  return '<div class="asx">' + ({ screens: rvScreens, assessment: rvAssessment, decisions: rvDecisions }[v] || rvScreens)() + '</div>';
};
ACT.goLook = (el) => { UI.look = el.dataset.look; go(el.dataset.route); };
function rvScreens() {
  const L = (route, label, small, look) => '<a href="#" ' + (look ? 'data-act="goLook" data-look="' + look + '" data-route="' + route + '"' : 'data-act="goOffice" data-route="' + route + '"') + '>' + label + (small ? '<small>' + small + '</small>' : '') + '</a>';
  const groups = [
    ['The module', [['overview', 'Overview', 'What needs attention, deep dives, recent changes'], ['processes', 'Processes', 'Search, quick filters, fold, ⋯ menu, New process'], ['deleted', 'Deleted processes', 'Restore one'], ['settings', 'Processes settings', 'Logo and colours, profiles, categories']]],
    ['One process · Order-to-Cash', [['p~ORD100~overview', 'Overview', 'Purpose, scope, measures, hand-overs, who is involved'], ['p~ORD100~map', 'Map', 'Swimlanes; click a step; add, edit, delete'], ['p~ORD100~raci', 'RACI', 'Final; reopen to change letters'], ['p~ORD100~authority', 'Authority', 'Rules by money and time'], ['p~ORD100~risks', 'Risks & controls', 'One risk has no control'], ['p~ORD100~quality', 'Quality', 'Non-conformances'], ['p~ORD100~lifecycle', 'Lifecycle', 'Approved; publish it to staff'], ['sop~ORD100', 'SOP document', 'Red Missing where nothing is recorded']]],
    ['Other states worth seeing', [['p~INV100~raci', 'A RACI with gaps', 'Suggest, fill, then mark final'], ['p~CRE100~map', 'Gaps on the map', 'Steps with no authority rule'], ['p~PRO100~map', 'A loop back', 'Decision “No, revise” drawn below'], ['p~PRO100~lifecycle', 'In review', 'Waiting on the approver'], ['p~HIR100~lifecycle', 'A draft to send', 'Pick an approver, say what changed'], ['p~CUS100~map', 'An empty process', 'Draft it with AI, or add steps'], ['p~NEW100~lifecycle', 'Review overdue', 'Published, past its review date']]],
    ['Priorities', [['priorities~score', 'Score', 'Weights, dots, suggestions, decisions'], ['priorities~rank', 'Rank', 'Bubble chart and the ranked list'], ['priorities~plan', 'Plan', 'Waves against team capacity'], ['priorities~signoff', 'Sign-off', 'Send the one page to the client']]],
    ['Landscape', [['landscape~rails', 'Milestones', 'One rail per process'], ['landscape~cards', 'Cards', 'Processes and their connections'], ['landscape~chain', 'Value chain', 'Every step, by phase or by owner']]],
    ['Governance', [['governance~attention', 'What needs attention', 'Tiles and the review calendar'], ['governance~assessment', 'Assessment', 'Aspects, governing policy, checklist'], ['governance~risks', 'Risk register', 'Heat map, treatment'], ['governance~policies', 'Policy library', 'Open one for its approvals'], ['governance~controls', 'Controls & KPIs', 'From each process'], ['governance~activity', 'Activity', 'Who changed what']]],
    ['Org directory and export', [['org~people', 'People', 'From the People register'], ['org~roles', 'Roles', 'Used by every map and matrix'], ['org~chart', 'Org chart', 'From “Reports to”'], ['export', 'Export report', 'Pick, check, preview']]],
  ];
  return '<h2 class="hd">Every screen</h2><p class="lead">Each link opens the screen in the prototype. Change things freely; <b>Start over</b> in the band puts every sample back. <b>Options</b> switches between the answers the team is weighing.</p><div class="idx" style="margin-top:18px">' +
    groups.map(([t, items]) => '<section><h4>' + t + '</h4>' + items.map(([r, l, s]) => L(r, l, s)).join('') + '</section>').join('') +
    '<section><h4>What a client\'s own people see</h4>' + L('read', 'Reading list · Dalia Sabry', 'Published processes; one needs her acknowledgement', 'staff') + L('read~ORD100', 'Reading a process', '“I have read this”', 'staff') + L('read', 'Approver\'s list · Yara Kamal', 'Procure-to-Pay waits for her approval', 'approver') + L('approve~PRO100', 'Approving a version', 'Approve, or send back with a reason', 'approver') + L('plan-signoff', 'Signing the deep-dive plan', 'Send the plan from Priorities › Sign-off first', 'approver') + '</section></div>';
}
ACT.goOffice = (el) => { UI.look = 'office'; go(el.dataset.route); };
function rvAssessment() {
  const F = [
    ['bad', 'Confuses', 'The navigation changes under you', 'On a process\'s page and its map you get the tabs. Open RACI, Authority or AI review and the tabs are gone; the only way back to Risks, Quality or Lifecycle is the strip\'s “Process” step, which lands on Overview first.', 'One header and one row of tabs on every view of a process.', 'p~ORD100~raci'],
    ['attn', 'Slows you down', 'Read in one place, edited in another', 'Purpose and scope are shown on Overview and document control on Lifecycle, but all three are edited on the map page, above the drawing. The Lifecycle tab says so: “Edit these on the process map page.”', 'Edit where you read it, with a pen on each block.', 'p~ORD100~overview'],
    ['attn', 'Slows you down', 'Switching process means going back to the list', 'From Order-to-Cash\'s RACI to Procure-to-Pay\'s RACI: left menu, find the row, Open, then RACI. Four clicks, through Overview.', 'A rail of processes beside the page, as Strategy lists a unit\'s pillars. You stay on the tab.', 'p~PRO100~raci'],
    ['bad', 'Confuses', 'Two measures of progress that disagree', 'The strip counts Process, Map, RACI, Authority, AI Review and marks one NEXT. The deep-dive plan counts Map, RACI, Authority, Controls, SOP, Approved. Authority never turns green on the strip, so a finished process says “Authority Matrix, NEXT” for ever.', 'One readiness line: the six marks, each a link to where it is fixed.', 'p~INV100~overview'],
    ['bad', 'Confuses', 'Three tabs that lead nowhere', 'People, Compliance and Connections say “not recorded yet” and offer nothing to record it with.', 'Off the row until they hold something. Who is involved and the hand-overs go on Overview.', 'p~ORD100~overview'],
    ['attn', 'Slows you down', 'The main buttons are at the bottom', 'New process, Draft with AI and Import sit under the whole list. Add step sits under the map.', 'One New process button at the top with the three ways in its menu; Add step in the map\'s toolbar.', 'processes'],
    ['attn', 'Slows you down', 'The list is hard to act on', 'Nine columns in an 848-pixel column. Every row carries Edit, Clone, Delete and Open, and the name is not a link. No owner column.', 'The row opens the process. Edit, Clone and Delete go behind ⋯. Owner and readiness come in.', 'processes'],
    ['attn', 'Slows you down', 'The front page is a settings page', '“Dashboard” holds the logo and colours, industry and description, and three counts. Nothing on it says what needs doing.', 'An Overview that opens on what needs attention.', 'overview'],
    ['attn', 'Slows you down', 'Governance is one long page', 'Dashboard, review calendar, profile form, assessment, activity log, then a block for every process, in one scroll.', 'Six views under one switch.', 'governance~attention'],
    ['attn', 'Slows you down', 'No way up', 'A sub-process names its parent in grey text that is not a link, and no process page has a trail back to the list.', 'A trail on every page: client · Processes › parent › this one.', 'p~ORD101~overview'],
    ['navy', 'Another product', 'It does not look like SMP', 'Its own typeface (Geist, not Source Sans), indigo and slate instead of navy and gold, the client\'s colour as a banner on some pages and a plain title on others, and a left menu where every other module has a bar along the top.', 'SMP\'s palette, type, tables, cards and section bar throughout.', 'overview'],
    ['', 'Polish', 'Names that need explaining', '“Helicopter View” is consultant shorthand; “Export Report” is a thing you do, sitting in the menu as a place.', 'Landscape, with Milestones, Cards and Value chain. Export as a button.', 'landscape~rails'],
  ];
  return '<h2 class="hd">How easy is Processes to get around today?</h2><p class="lead">Counted from the module as it stands on 23 October 2026. The parts are good; the paths between them are where the time goes, and most of that is on a process\'s own page.</p>' +
    '<div class="msr"><div><b>8</b><span>items in the left menu, mixing the work, whole-company views, setup and output</span></div><div><b>4</b><span>ways to move around one process on one screen</span></div><div><b>11</b><span>places one process\'s information lives: seven tabs and four pages</span></div><div><b>3 of 7</b><span>tabs empty, with no way to fill them</span></div><div><b>2</b><span>measures of progress that disagree</span></div></div>' +
    '<h3 class="h3">What makes it hard, worst first</h3><p class="note">Each one says what was counted and where the prototype answers it.</p><div class="findings">' +
    F.map(([tone, sev, h, p, fix, route]) => '<div class="fd"><div><span class="chip ' + tone + '">' + sev + '</span></div><div><h4>' + h + '</h4><p>' + p + '</p><div class="fix"><b>Fix</b>' + fix + ' <button class="lnk" type="button" data-act="goOffice" data-route="' + route + '">See it</button></div></div></div>').join('') + '</div>' +
    '<h3 class="h3">Six everyday jobs, counted</h3><p class="note">Clicks from wherever you would naturally be.</p><div class="tw"><table class="t ts"><thead><tr><th>Job</th><th>Today</th><th>In the prototype</th></tr></thead><tbody>' +
    [['See what needs doing this week', 'Not on one page', 'Overdue reviews are a word in a column; RACI drafts a count on Dashboard.', '0 clicks', 'The first block on Overview.'],
     ['From Order-to-Cash\'s RACI to Procure-to-Pay\'s', '4 clicks', 'Menu, find the row, Open, RACI.', '1 click', 'Procure-to-Pay in the rail; RACI stays open.'],
     ['Change a purpose you are reading', '2 clicks', 'Open process map, then Edit on Documentation.', '1 click', 'The pen on Purpose.'],
     ['Record a risk while on RACI', '2 clicks + scroll', 'Strip\'s Process step, Risks tab, form at the bottom.', '2 clicks', 'Risks & controls tab, Add a risk at the top.'],
     ['Start a new process', 'Scroll past every row', '', '1 click', 'New process, top right.'],
     ['See why a process is not ready', '2 pages', 'The strip, then the card on Priorities.', '0 clicks', 'The readiness line; each mark is a link.']].map(([j, a, aw, b, bw]) => '<tr><td><b>' + j + '</b></td><td><span class="big bad">' + a + '</span>' + (aw ? '<br><span class="q">' + aw + '</span>' : '') + '</td><td><span class="big good">' + b + '</span><br><span class="q">' + bw + '</span></td></tr>').join('') + '</tbody></table></div>';
}
function rvDecisions() {
  const Q = [
    ['Should Processes take SMP\'s look?', 'On 1 October you chose to keep FFProcess\'s own design when it came into SMP. This reverses that, and is recorded as a reversal.', [['SMP\'s look throughout: navy and gold, Source Sans, navy-headed tables, the section bar.', 'Every Processes page is restyled. The client\'s colour moves to the report and the SOP.', true], ['SMP\'s look, but keep the client\'s colour on each page title.', 'Closer to today; the one place Processes differs from Portfolio and the Tracker.', false, { brand: true }]]],
    ['Swap the left menu for a section bar along the top?', 'Eight items become six. Export becomes a button. Logo, colours and the client profile move to Processes settings in the top bar\'s Processes menu.', [['Yes, as drawn.', 'The page gets back the 224 pixels the menu takes, and Processes moves the way Strategy does.', true], ['Keep the left menu, restyled.', 'Less change for people used to it.', false, { nav: 'side' }]]],
    ['Put Helicopter View and Value Chain together as “Landscape”?', 'Both show the whole company at once. As one section they are three views under one switch.', [['One section, called Landscape. The name is yours to choose.', '', true], ['Keep them as two sections.', 'Seven items on the bar instead of six.', false, { landscape: false }]]],
    ['Take the three empty tabs off a process for now?', 'People, Compliance and Connections were in the structure signed off on 14 October. Today they hold nothing and offer nothing to fill in.', [['Off for now; back as each one gets content.', 'Changes what was signed off on 14 October; recorded as a change.', true], ['Keep all seven tabs as signed off.', 'Three tabs keep saying “not recorded yet”.', false, { oldTabs: true }]]],
    ['One measure of readiness: the six deep-dive marks?', 'The five-step strip goes; the header shows Map, RACI, Authority, Controls, SOP and Approved. “Next” names what is missing.', [['Six marks on every process, deep dive or not.', 'A high-level process shows mostly empty marks. That is true, and the list says High-level beside it.', true], ['Six marks on deep dives only.', 'Quieter for high-level processes, and two kinds of process header.', false, { marksAll: false }]]],
    ['A list of processes beside every process page?', 'The rail, as Strategy lists a unit\'s pillars. Switching keeps the tab. On Map it folds away so the drawing gets the width.', [['Yes, folded away on Map only.', '', true], ['No rail; switch process from the list.', 'Switching stays four clicks.', false, { rail: false }]]],
    ['AI review as a panel beside any tab, not a page?', '“Check with AI” opens over whichever tab you are on, with “Add as a step” and “Add a control” right there.', [['A panel, from a button in the header.', '', true], ['Its own tab.', 'An eighth tab.', false, { aiPanel: false }]]],
  ];
  return '<h2 class="hd">What the team needs to decide</h2><p class="lead">Seven product questions. The prototype opens on the recommended answers; <b>Try it</b> switches to the other one so you can compare on the screen. Nothing is built until you say so.</p><div class="qs" style="margin-top:18px">' +
    Q.map(([h, p, opts], i) => '<div class="qq"><span class="qn">' + (i + 1) + '</span><h4>' + h + '</h4><p>' + p + '</p><div class="opts">' + opts.map(([t, c, rec, set], j) => '<div class="opt' + (rec ? ' rec' : '') + '"><b class="k">' + 'AB'[j] + '</b><span>' + t + (rec ? '<span class="rt">Recommended</span>' : '') + (c ? '<span class="c">' + c + '</span>' : '') + (set ? '<button class="lnk seeit" type="button" data-act="tryOpt" data-set="' + esc(JSON.stringify(set)) + '">Try it</button>' : '') + '</span></div>').join('') + '</div></div>').join('') + '</div>' +
    '<h3 class="h3">If the team says go, the order to build it in</h3><p class="note">Each step ships on its own and leaves the module working.</p><div class="qs">' +
    [['The look and the frame', 'SMP\'s palette, type, tables and cards; the section bar; one page-header style. No behaviour changes.'], ['One process page', 'Map, RACI and Authority as tabs under one header; empty tabs off; edit where you read; the readiness line.'], ['The rail', 'The list of processes beside every process page, keeping the tab.'], ['The list', 'Rows open the process, ⋯ menu, owner and readiness, quick filters, New process at the top.'], ['Overview and settings', 'What needs attention; logo, colours and profiles move to Processes settings.'], ['Governance, Landscape, Check with AI', 'Six Governance views; one Landscape section; the AI panel.']].map(([t, d], i) => '<div class="qq" style="grid-template-columns:34px minmax(0,1fr)"><span class="qn" style="background:var(--surface-2);color:var(--stone)">' + (i + 1) + '</span><h4>' + t + '</h4><p>' + d + '</p></div>').join('') + '</div>';
}
ACT.tryOpt = (el) => {
  const set = JSON.parse(el.dataset.set); Object.assign(OPT, set); UI.look = 'office';
  const where = set.nav ? 'processes' : set.brand ? 'overview' : set.landscape === false ? 'landscape~rails' : set.oldTabs ? 'p~ORD100~people' : set.marksAll === false ? 'processes' : set.rail === false ? 'p~ORD100~raci' : set.aiPanel === false ? 'p~ORD100~ai' : 'overview';
  toast('Option B is on. Options in the band switches it back.'); go(where);
};
